package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.ai.Usage;
import java.util.OptionalLong;

/** Compaction thresholds; automatic compaction requires a negotiated model context window. */
public record CompactionPolicy(
        boolean automatic,
        OptionalLong contextWindowTokens,
        int reserveTokens,
        int keepRecentTokens) {
    public static final int DEFAULT_RESERVE_TOKENS = 16_384;
    public static final int DEFAULT_KEEP_RECENT_TOKENS = 20_000;

    public CompactionPolicy {
        contextWindowTokens = contextWindowTokens == null ? OptionalLong.empty() : contextWindowTokens;
        if (reserveTokens < 1 || keepRecentTokens < 1) {
            throw new IllegalArgumentException("compaction token budgets must be positive");
        }
        if (automatic && contextWindowTokens.isEmpty()) {
            throw new IllegalArgumentException("automatic compaction requires a context window");
        }
        contextWindowTokens.ifPresent(value -> {
            if (value <= reserveTokens) {
                throw new IllegalArgumentException("context window must exceed compaction reserve");
            }
        });
    }

    public static CompactionPolicy manualOnly() {
        return new CompactionPolicy(false, OptionalLong.empty(),
                DEFAULT_RESERVE_TOKENS, DEFAULT_KEEP_RECENT_TOKENS);
    }

    public static CompactionPolicy automatic(long contextWindowTokens) {
        return new CompactionPolicy(true, OptionalLong.of(contextWindowTokens),
                DEFAULT_RESERVE_TOKENS, DEFAULT_KEEP_RECENT_TOKENS);
    }

    public boolean shouldCompact(Usage usage) {
        if (!automatic || usage == null) return false;
        long observed = usage.totalTokens();
        return observed >= contextWindowTokens.orElseThrow() - reserveTokens;
    }

    public boolean isContextOverflow(Usage usage) {
        return automatic && usage != null
                && usage.totalTokens() >= contextWindowTokens.orElseThrow();
    }

    public boolean isContextOverflow(Usage usage) {
        return automatic && usage != null
                && usage.totalTokens() >= contextWindowTokens.orElseThrow();
    }
}
